                "type": "inconsistent_row",
                "sample_id": row_labels[r],
                "residual": _frac_to_str(mat[r][n]),
            }

    sol = [Fraction(0, 1)] * n
    for r, piv in enumerate(pivot_cols):
        sol[piv] = mat[r][n]

    return True, sol, rank_a, rank_aug, None


